"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[2395],{6448(n,e,i){i.r(e),i.d(e,{assets:()=>d,contentTitle:()=>c,default:()=>h,frontMatter:()=>l,metadata:()=>a,toc:()=>p});const a=JSON.parse('{"id":"part4-ml-foundations/linear-classification","title":"Linear Classification in PyTorch","description":"A student-friendly chapter that explains linear decision boundaries, logistic regression, and a complete PyTorch training loop end-to-end. Diagrams are saved locally under assets/images/ch4 (downloaded from Wikimedia...","source":"@site/docs/part4-ml-foundations/04-linear-classification.mdx","sourceDirName":"part4-ml-foundations","slug":"/part4-ml-foundations/04-linear-classification","permalink":"/tutorials/part4-ml-foundations/04-linear-classification","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":4,"frontMatter":{"title":"Linear Classification in PyTorch","slug":"/part4-ml-foundations/04-linear-classification","description":"A student-friendly chapter that explains linear decision boundaries, logistic regression, and a complete PyTorch training loop end-to-end. Diagrams are saved locally under assets/images/ch4 (downloaded from Wikimedia...","sidebar_label":"4. Linear classification","pagination_label":"4. Linear classification","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"3. Linear regression","permalink":"/tutorials/part4-ml-foundations/03-linear-regression"},"next":{"title":"5. Trees, bagging, and boosting","permalink":"/tutorials/part4-ml-foundations/05-trees-bagging-boosting"}}');var t=i(4848),s=i(8453),o=i(8172);const r=JSON.parse('{"sourcePath":"part4-ml-foundations/04-linear-classification.html","route":"/part4-ml-foundations/04-linear-classification","kind":"chapter","partId":"part4","partLabel":"Part IV - Machine Learning Foundations","accent":"amber","heading":"Linear Classification in PyTorch","title":"Linear Classification in PyTorch","description":"A student-friendly chapter that explains linear decision boundaries, logistic regression, and a complete PyTorch training loop end-to-end. Diagrams are saved locally under assets/images/ch4 (downloaded from Wikimedia...","readingMinutes":12,"bodyClass":"","normalizeMath":true,"toc":[{"id":"1-the-ml-workflow-what-happens-inside-fitpredictscore","label":"1) The ML Workflow: What Happens Inside fitpredictscore?"},{"id":"2-classification-accuracy-and-error","label":"2) Classification Accuracy and Error"},{"id":"3-geometry-linear-decision-boundary-and-the-logit","label":"3) Geometry: Linear Decision Boundary and the Logit"},{"id":"4-step-function-vs-sigmoid-logistic-regression","label":"4) Step Function vs Sigmoid: Logistic Regression"},{"id":"5-training-loss-functions-gradients-and-learning-rate","label":"5) Training: Loss Functions, Gradients, and Learning Rate"},{"id":"6-dataset-breast-cancer-scikit-learn-preprocessing","label":"6) Dataset: Breast Cancer (scikit-learn) + Preprocessing"},{"id":"7-pytorch-implementation-logistic-regression-end-to-end","label":"7) PyTorch Implementation: Logistic Regression End-to-End"},{"id":"8-a-better-logistic-regression-in-pytorch-bcewithlogitsloss","label":"8) A Better Logistic Regression in PyTorch: BCEWithLogitsLoss"},{"id":"9-saving-and-loading-models-and-downloading-from-colab","label":"9) Saving and Loading Models (and Downloading from Colab)"},{"id":"10-why-logistic-regression-is-a-neuron","label":"10) Why Logistic Regression is a \u201cNeuron\u201d"},{"id":"11-train-validation-test-why-splits-exist-and-how-kaggle-changes-the-words","label":"11) Train / Validation / Test: Why Splits Exist (and How Kaggle Changes the Words)"},{"id":"12-summary-exercises","label":"12) Summary + Exercises"}],"html":"<div class=\\"container\\">\\n    <header>\\n      \\n      <p>\\n        A student-friendly chapter that explains linear decision boundaries, logistic regression, and a complete\\n        PyTorch training loop end-to-end.\\n        Diagrams are saved locally under <code>assets/images/ch4</code> (downloaded from Wikimedia Commons) so the\\n        page works offline.\\n      </p>\\n      <div class=\\"badge\\">Light theme \u2022 VSCode-like code blocks \u2022 LaTeX via KaTeX \u2022 Offline diagrams</div>\\n\\n      <nav class=\\"toc\\" aria-label=\\"Table of contents\\">\\n        <a href=\\"#workflow\\">1) The ML workflow and what happens inside fit/predict/score</a>\\n        <a href=\\"#accuracy\\">2) Accuracy, error, train vs test</a>\\n        <a href=\\"#geometry\\">3) Linear decision boundaries and the logit</a>\\n        <a href=\\"#sigmoid\\">4) Step vs sigmoid, logistic regression</a>\\n        <a href=\\"#training\\">5) Training: loss, gradient descent, learning rate</a>\\n        <a href=\\"#dataset\\">6) Dataset: Breast cancer (scikit-learn) + preprocessing</a>\\n        <a href=\\"#pytorch\\">7) PyTorch implementation: BCE, Adam, training loop, accuracy</a>\\n        <a href=\\"#stability\\">8) Better logistic regression: BCEWithLogitsLoss</a>\\n        <a href=\\"#save\\">9) Saving/loading models (state_dict) + Colab download</a>\\n        <a href=\\"#neuron\\">10) Why logistic regression is a \u201cneuron\u201d</a>\\n        <a href=\\"#splits\\">11) Train/validation/test, Kaggle, cross-validation, hyperparameters</a>\\n        <a href=\\"#summary\\">12) Summary + exercises</a>\\n      </nav>\\n    </header>\\n\\n    <div class=\\"callout.green\\">\\n      <div class=\\"title\\">What you\u2019ll build (and the math behind it)</div>\\n      <ul>\\n        <li>\\n          A <strong>linear classifier</strong> with logit $a = w^\\\\top x + b$ and probability\\n          $p = \\\\sigma(a)$.\\n        </li>\\n        <li>\\n          A training objective (binary cross-entropy) and a training loop that minimizes it:\\n          $$\\\\theta^* = \\\\arg\\\\min_{\\\\theta} \\\\frac{1}{n}\\\\sum_{i=1}^{n} \\\\ell\\\\bigl(a_i(\\\\theta), y_i\\\\bigr).$$\\n        </li>\\n        <li>\\n          Practical evaluation: accuracy on train vs test, and how to spot overfitting.\\n        </li>\\n      </ul>\\n      <p class=\\"mini\\">\\n        Notation used throughout: $x\\\\in\\\\mathbb{R}^D$ (features), $y\\\\in\\\\{0,1\\\\}$ (label),\\n        $w\\\\in\\\\mathbb{R}^D$ (weights), $b\\\\in\\\\mathbb{R}$ (bias).\\n      </p>\\n    </div>\\n\\n    \x3c!-- ===================================================== --\x3e\\n    <section id=\\"workflow\\">\\n      <h2 id=\\"1-the-ml-workflow-what-happens-inside-fitpredictscore\\">1) The ML Workflow: What Happens Inside <span class=\\"pill\\">fit</span><span class=\\"pill\\">predict</span><span class=\\"pill\\">score</span>?</h2>\\n\\n      <p>\\n        A typical scikit-learn-style workflow follows the same outer structure for many models:\\n      </p>\\n\\n      <ol>\\n        <li>Load data into inputs \\\\(X\\\\) and targets \\\\(y\\\\).</li>\\n        <li>Instantiate a model (e.g., logistic regression, linear regression, etc.).</li>\\n        <li>Train it with something like <code>model.fit(X, y)</code>.</li>\\n        <li>Make predictions with <code>model.predict(X)</code> (on train or on new/test data).</li>\\n        <li>Evaluate with <code>model.score(X, y)</code>.</li>\\n      </ol>\\n\\n      <div class=\\"callout.blue\\">\\n        <div class=\\"title\\">Why this question matters</div>\\n        <p>\\n          On the surface, \u201clinear regression\u201d and \u201clogistic regression\u201d can look identical in code:\\n          you mostly change the class name. The difference is what the model computes, what loss it minimizes,\\n          and how training updates parameters. <strong>The inside of these functions is where the real meaning is.</strong>\\n        </p>\\n        <p class=\\"mini\\">\\n          In math terms, <span class=\\"pill\\">fit</span> is \u201cchoose parameters to minimize a loss\u201d,\\n          <span class=\\"pill\\">predict</span> is \u201crun the model forward\u201d, and <span class=\\"pill\\">score</span>\\n          is \u201ccompute a metric\u201d. For classification, the most common metric is accuracy.\\n        </p>\\n      </div>\\n    </section>\\n\\n    \x3c!-- ===================================================== --\x3e\\n    <section id=\\"accuracy\\">\\n      <h2 id=\\"2-classification-accuracy-and-error\\">2) Classification Accuracy and Error</h2>\\n\\n      <p>\\n        In binary classification (e.g., spam vs not-spam), every prediction is either correct or incorrect.\\n      </p>\\n\\n      <p>\\n        $$\\\\text{accuracy}=\\\\frac{\\\\#\\\\text{correct}}{\\\\#\\\\text{total}}, \\\\qquad\\n          \\\\text{error}=\\\\frac{\\\\#\\\\text{wrong}}{\\\\#\\\\text{total}}=1-\\\\text{accuracy}.$$\\n      </p>\\n\\n      <p>\\n        Equivalently, using an indicator function $\\\\mathbf{1}[\\\\cdot]$:\\n        $$\\\\text{accuracy} = \\\\frac{1}{n}\\\\sum_{i=1}^{n}\\\\mathbf{1}[\\\\hat{y}_i = y_i].$$\\n      </p>\\n\\n      <div class=\\"callout.green\\">\\n        <div class=\\"title\\">Train vs test accuracy</div>\\n        <p>\\n          You can compute accuracy on the training set and on a held-out test set:\\n          <strong>train accuracy</strong> measures how well you fit the seen data,\\n          while <strong>test accuracy</strong> estimates how well you generalize to unseen data.\\n        </p>\\n        <p class=\\"mini\\">\\n          Note: if classes are highly imbalanced (e.g., 99% of samples are class 0), accuracy can be misleading.\\n          It\u2019s still a good starting point, but you may later want precision/recall or ROC-AUC.\\n        </p>\\n      </div>\\n    </section>\\n\\n    \x3c!-- ===================================================== --\x3e\\n    <section id=\\"geometry\\">\\n      <h2 id=\\"3-geometry-linear-decision-boundary-and-the-logit\\">3) Geometry: Linear Decision Boundary and the Logit</h2>\\n\\n      <p>\\n        A linear classifier draws a boundary in feature space.\\n        For a 2D input \\\\(x=(x_1,x_2)\\\\), the boundary is a line:\\n      </p>\\n\\n      <p>\\n        $$w_1x_1+w_2x_2+b=0.$$\\n      </p>\\n\\n      <p>\\n        This form generalizes cleanly to higher dimensions (where the boundary is a hyperplane).\\n        It also connects directly to the key scalar quantity the model computes:\\n      </p>\\n\\n      <p>\\n        $$a=w^\\\\top x + b,$$\\n      </p>\\n\\n      <p>\\n        where \\\\(a\\\\) is commonly called the <strong>activation</strong> or <strong>logit</strong>.\\n      </p>\\n\\n      <div class=\\"callout.blue\\">\\n        <div class=\\"title\\">Signed distance intuition</div>\\n        <p>\\n          The value $a = w^\\\\top x + b$ tells you which side of the boundary you\u2019re on.\\n          If you normalize by $\\\\lVert w\\\\rVert$, then $\\\\frac{a}{\\\\lVert w\\\\rVert}$ is proportional to the signed distance\\n          from the point to the hyperplane.\\n        </p>\\n      </div>\\n\\n      <div class=\\"callout.orange\\">\\n        <div class=\\"title\\">Why not just use \\\\(y=mx+b\\\\)?</div>\\n        <p>\\n          In classification, the axes are features \\\\(x_1,x_2,\\\\dots\\\\). The label \\\\(y\\\\) is <em>not an axis</em>.\\n          The vector form \\\\(w^\\\\top x+b\\\\) works for any number of features \\\\(D\\\\), not just 2.\\n        </p>\\n      </div>\\n\\n      <h3 id=\\"from-geometry-to-prediction-sign-test\\">From geometry to prediction (sign test)</h3>\\n      <p>\\n        If a point is not on the boundary, then \\\\(a=w^\\\\top x+b\\\\) will be either positive or negative.\\n        One side of the hyperplane always yields \\\\(a&gt;0\\\\), the other yields \\\\(a&lt;0\\\\).\\n      </p>\\n\\n      <p>\\n        $$\\\\hat{y}=\\\\begin{cases}\\n          1 &amp; \\\\text{if } a&gt;0 \\\\\\\\\\n          0 &amp; \\\\text{if } a\\\\le 0\\n        \\\\end{cases}$$\\n      </p>\\n\\n      <figure>\\n        \x3c!-- Wikimedia image (decision boundaries / hyperplanes) --\x3e\\n        <img alt=\\"SVM separating hyperplanes diagram (used here to visualize linear decision boundaries)\\" src=\\"/tutorials/images/ch4/svm-separating-hyperplanes.svg\\">\\n        <figcaption>\\n          Wikimedia diagram illustrating separating hyperplanes (used here purely as a visual intuition for linear decision boundaries).\\n          The lecture\u2019s key idea matches the hyperplane form \\\\(w^\\\\top x + b = 0\\\\).\\n        </figcaption>\\n      </figure>\\n    </section>\\n\\n    \x3c!-- ===================================================== --\x3e\\n    <section id=\\"sigmoid\\">\\n      <h2 id=\\"4-step-function-vs-sigmoid-logistic-regression\\">4) Step Function vs Sigmoid: Logistic Regression</h2>\\n\\n      <p>\\n        The sign test is like a hard \u201cstep function.\u201d In deep learning we prefer smooth differentiable functions,\\n        so we often map the logit \\\\(a\\\\) through a sigmoid:\\n      </p>\\n\\n      <p>\\n        $$\\\\sigma(a)=\\\\frac{1}{1+e^{-a}} \\\\in (0,1).$$\\n      </p>\\n\\n      <p>\\n        We interpret \\\\(p=\\\\sigma(a)\\\\) as a probability:\\n      </p>\\n\\n      <p>\\n        $$p(y=1\\\\mid x)=\\\\sigma(w^\\\\top x + b).$$\\n      </p>\\n\\n      <p>\\n        A useful identity: the log-odds are linear in $x$:\\n        $$\\\\log\\\\frac{p}{1-p} = w^\\\\top x + b.$$\\n        This is one reason logistic regression is so interpretable.\\n      </p>\\n\\n      <p>\\n        And convert to a class prediction by thresholding:\\n      </p>\\n\\n      <p>\\n        $$\\\\hat{y}=\\\\mathbf{1}[p\\\\ge 0.5].$$\\n      </p>\\n\\n      <div class=\\"callout.purple\\">\\n        <div class=\\"title\\">Terminology you\u2019ll see</div>\\n        <ul>\\n          <li><strong>Logistic function</strong> = sigmoid function.</li>\\n          <li><strong>Logit</strong> = the sigmoid input \\\\(a=w^\\\\top x+b\\\\).</li>\\n          <li><strong>Logistic regression</strong> = linear model + sigmoid for binary classification.</li>\\n        </ul>\\n      </div>\\n\\n      <figure>\\n        <img alt=\\"Sigmoid function plot\\" src=\\"/tutorials/images/ch4/sigmoid-function.svg\\">\\n        <figcaption>\\n          Sigmoid curve from Wikimedia. It smoothly maps any real logit \\\\(a\\\\) to a probability in \\\\((0,1)\\\\).\\n          Note: \\\\(a=0 \\\\Rightarrow \\\\sigma(a)=0.5\\\\).\\n        </figcaption>\\n      </figure>\\n    </section>\\n\\n    \x3c!-- ===================================================== --\x3e\\n    <section id=\\"training\\">\\n      <h2 id=\\"5-training-loss-functions-gradients-and-learning-rate\\">5) Training: Loss Functions, Gradients, and Learning Rate</h2>\\n\\n      <h3 id=\\"regression-vs-classification-why-the-loss-changes\\">Regression vs classification: why the loss changes</h3>\\n      <p>\\n        In regression, targets \\\\(y\\\\in\\\\mathbb{R}\\\\), predictions \\\\(\\\\hat{y}\\\\in\\\\mathbb{R}\\\\), so losses like mean squared error (MSE) make sense:\\n      </p>\\n      <p>\\n        $$\\\\text{MSE}=\\\\frac{1}{n}\\\\sum_{i=1}^{n}(y_i-\\\\hat{y}_i)^2.$$\\n      </p>\\n\\n      <p>\\n        In binary classification, the model outputs probabilities, and a standard loss is <strong>binary cross-entropy</strong>:\\n      </p>\\n      <p>\\n        $$\\\\mathcal{L}_{\\\\text{BCE}} = -\\\\frac{1}{n}\\\\sum_{i=1}^{n}\\\\left[y_i\\\\log(p_i) + (1-y_i)\\\\log(1-p_i)\\\\right],\\\\quad p_i=\\\\sigma(a_i).$$\\n      </p>\\n\\n      <div class=\\"callout.purple\\">\\n        <div class=\\"title\\">Where BCE comes from (one sentence)</div>\\n        <p>\\n          If you assume $y\\\\mid x$ follows a Bernoulli distribution with probability $p=\\\\sigma(w^\\\\top x+b)$,\\n          then minimizing BCE is exactly minimizing the <strong>negative log-likelihood</strong>.\\n        </p>\\n      </div>\\n\\n      <div class=\\"callout.blue\\">\\n        <div class=\\"title\\">Loss / cost / objective</div>\\n        <p>\\n          The lecture used these words interchangeably: they all mean \u201cthe scalar we minimize during training.\u201d\\n        </p>\\n      </div>\\n\\n      <h3 id=\\"how-does-a-model-learn\\">How does a model learn?</h3>\\n      <p>\\n        PyTorch uses <strong>automatic differentiation</strong> to compute gradients of the loss with respect to parameters\\n        \\\\(w\\\\) and \\\\(b\\\\). Gradient descent updates parameters iteratively:\\n      </p>\\n\\n      <p>\\n        $$w \\\\leftarrow w - \\\\eta \\\\frac{\\\\partial \\\\mathcal{L}}{\\\\partial w},\\\\qquad\\n          b \\\\leftarrow b - \\\\eta \\\\frac{\\\\partial \\\\mathcal{L}}{\\\\partial b},$$\\n      </p>\\n\\n      <p>\\n        where \\\\(\\\\eta\\\\) is the <strong>learning rate</strong>.\\n      </p>\\n\\n      <div class=\\"callout.orange\\">\\n        <div class=\\"title\\">Learning rate is a hyperparameter</div>\\n        <p>\\n          It is not learned by the model; you choose it (often by trial + intuition).\\n          A common starting sweep is \\\\(10^{-1},10^{-2},10^{-3},\\\\dots\\\\).\\n        </p>\\n      </div>\\n\\n      <figure>\\n        <img alt=\\"Gradient descent animation\\" src=\\"/tutorials/images/ch4/gradient-descent.gif\\">\\n        <figcaption>\\n          Gradient descent animation (Wikimedia). It shows repeated steps moving \u201cdownhill\u201d along the loss landscape.\\n          The step size relates to the learning rate.\\n        </figcaption>\\n      </figure>\\n    </section>\\n\\n    \x3c!-- ===================================================== --\x3e\\n    <section id=\\"dataset\\">\\n      <h2 id=\\"6-dataset-breast-cancer-scikit-learn-preprocessing\\">6) Dataset: Breast Cancer (scikit-learn) + Preprocessing</h2>\\n\\n      <p>\\n        The lecture uses the well-known breast cancer dataset included in scikit-learn.\\n        Loading it is a single function call (no manual download needed):\\n      </p>\\n\\n      <ul>\\n        <li>Inputs: <code>data.data</code> \\\\(\\\\rightarrow X\\\\)</li>\\n        <li>Targets: <code>data.target</code> \\\\(\\\\rightarrow y\\\\) (0/1)</li>\\n        <li>Names: <code>data.target_names</code>, <code>data.feature_names</code></li>\\n      </ul>\\n\\n      <div class=\\"callout.green\\">\\n        <div class=\\"title\\">Two preprocessing steps from the lecture</div>\\n        <ol>\\n          <li><strong>Train/test split</strong> so we can evaluate on unseen data.</li>\\n          <li><strong>Standardization</strong> with <code>StandardScaler</code>:\\n            fit on train only, then transform train and test using the train mean/std.</li>\\n        </ol>\\n        <p class=\\"mini\\">\\n          Standardization is: $$x\' = \\\\frac{x-\\\\mu}{\\\\sigma}$$\\n          computed per feature (dimension). It helps optimization because different features can start on very different scales.\\n        </p>\\n      </div>\\n    </section>\\n\\n    \x3c!-- ===================================================== --\x3e\\n    <section id=\\"pytorch\\">\\n      <h2 id=\\"7-pytorch-implementation-logistic-regression-end-to-end\\">7) PyTorch Implementation: Logistic Regression End-to-End</h2>\\n\\n      <p>\\n        We will implement the lecture\u2019s PyTorch pipeline:\\n        load data, split, scale, build model, train with gradient descent, then evaluate accuracy.\\n      </p>\\n\\n      <div class=\\"codeblock\\">\\n        <div class=\\"codebar\\">\\n          <div class=\\"left\\">\\n            <div class=\\"dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n            <span class=\\"lang\\">Python</span>\\n            <span class=\\"mini\\">Load + split + scale</span>\\n          </div>\\n          \\n        </div>\\n        <div class=\\"editor\\">\\n          <div class=\\"gutter\\"></div>\\n          <pre data-ln=\\"\\"><code id=\\"code-data\\" class=\\"language-python\\">import numpy as np\\nfrom sklearn.datasets import load_breast_cancer\\nfrom sklearn.model_selection import train_test_split\\nfrom sklearn.preprocessing import StandardScaler\\n\\n# 1) Load data (built into sklearn)\\ndata = load_breast_cancer()\\nX = data.data               # shape (n, D)\\ny = data.target             # shape (n,), values in {0,1}\\n\\n# (Optional inspection)\\nprint(\\"X shape:\\", X.shape)  # e.g., (569, 30)\\nprint(\\"y shape:\\", y.shape)\\nprint(\\"target names:\\", data.target_names)  # e.g., [\'malignant\', \'benign\']\\n\\n# 2) Train/test split (test_size ~ 33% as in the lecture)\\nX_train, X_test, y_train, y_test = train_test_split(\\n    X, y, test_size=0.33, random_state=123, stratify=y\\n)\\n\\n# 3) Standardize features\\nscaler = StandardScaler()\\nX_train = scaler.fit_transform(X_train)   # fit only on train\\nX_test  = scaler.transform(X_test)        # transform test using train stats\\n\\nn, D = X_train.shape\\nprint(\\"train:\\", X_train.shape, \\"test:\\", X_test.shape)</code></pre>\\n        </div>\\n      </div>\\n\\n      <h3 id=\\"model-linear-layer-sigmoid\\">Model: Linear layer + sigmoid</h3>\\n      <p>\\n        The lecture builds a logistic regression model as:\\n      </p>\\n      <p>\\n        $$p=\\\\sigma(w^\\\\top x+b),$$\\n      </p>\\n      <p>\\n        which in PyTorch can be represented as <code>nn.Linear(D,1)</code> then <code>nn.Sigmoid()</code>, wrapped in <code>nn.Sequential</code>.\\n      </p>\\n\\n      <div class=\\"callout.orange\\">\\n        <div class=\\"title\\">Shape sanity check</div>\\n        <p>\\n          For binary classification, it\u2019s common to keep outputs as shape $(n,1)$.\\n          That\u2019s why the targets are reshaped with <code>.view(-1, 1)</code>.\\n        </p>\\n      </div>\\n\\n      <div class=\\"codeblock\\">\\n        <div class=\\"codebar\\">\\n          <div class=\\"left\\">\\n            <div class=\\"dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n            <span class=\\"lang\\">Python</span>\\n            <span class=\\"mini\\">Model + loss + optimizer + tensor conversion</span>\\n          </div>\\n          \\n        </div>\\n        <div class=\\"editor\\">\\n          <div class=\\"gutter\\"></div>\\n          <pre data-ln=\\"\\"><code id=\\"code-model\\" class=\\"language-python\\">import torch\\nimport torch.nn as nn\\n\\n# Logistic regression = Linear + Sigmoid\\nmodel = nn.Sequential(\\n    nn.Linear(D, 1),\\n    nn.Sigmoid()\\n)\\n\\n# Binary cross entropy loss (for probabilities)\\ncriterion = nn.BCELoss()\\n\\n# Adam optimizer (common default in deep learning)\\noptimizer = torch.optim.Adam(model.parameters(), lr=1e-3)\\n\\n# Convert numpy -&gt; torch tensors (float32)\\nX_train_t = torch.from_numpy(X_train.astype(np.float32))\\nX_test_t  = torch.from_numpy(X_test.astype(np.float32))\\n\\n# IMPORTANT in PyTorch: y should be shape (n, 1) for this setup\\ny_train_t = torch.from_numpy(y_train.astype(np.float32)).view(-1, 1)\\ny_test_t  = torch.from_numpy(y_test.astype(np.float32)).view(-1, 1)</code></pre>\\n        </div>\\n      </div>\\n\\n      <h3 id=\\"training-loop-gradient-descent-with-autograd\\">Training loop (gradient descent with autograd)</h3>\\n      <p>\\n        The lecture\u2019s loop is the standard PyTorch pattern:\\n        zero gradients \u2192 forward pass \u2192 loss \u2192 backward \u2192 optimizer step.\\n      </p>\\n\\n      <div class=\\"codeblock\\">\\n        <div class=\\"codebar\\">\\n          <div class=\\"left\\">\\n            <div class=\\"dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n            <span class=\\"lang\\">Python</span>\\n            <span class=\\"mini\\">Train + track train/test loss (per epoch)</span>\\n          </div>\\n          \\n        </div>\\n        <div class=\\"editor\\">\\n          <div class=\\"gutter\\"></div>\\n          <pre data-ln=\\"\\"><code id=\\"code-train\\" class=\\"language-python\\">train_losses = []\\ntest_losses = []\\n\\nepochs = 300\\n\\nfor epoch in range(epochs):\\n    # ---- TRAIN step ----\\n    optimizer.zero_grad()\\n    p_train = model(X_train_t)                 # probabilities in (0,1)\\n    loss_train = criterion(p_train, y_train_t)\\n    loss_train.backward()\\n    optimizer.step()\\n\\n    # ---- EVAL losses (no gradient needed) ----\\n    with torch.no_grad():\\n        p_test = model(X_test_t)\\n        loss_test = criterion(p_test, y_test_t)\\n\\n    train_losses.append(loss_train.item())\\n    test_losses.append(loss_test.item())\\n\\n    if (epoch+1) % 50 == 0:\\n        print(f\\"epoch {epoch+1:4d}  train_loss={loss_train.item():.4f}  test_loss={loss_test.item():.4f}\\")</code></pre>\\n        </div>\\n      </div>\\n\\n      <div class=\\"callout.red\\">\\n        <div class=\\"title\\">Why \u201ctest loss increasing\u201d matters</div>\\n        <p>\\n          If training loss keeps decreasing but test/validation loss starts increasing,\\n          you may be overfitting (memorizing train patterns that don\u2019t generalize).\\n        </p>\\n      </div>\\n\\n      <figure>\\n        <img alt=\\"Overfitting curves: training error decreases while validation error increases\\" src=\\"/tutorials/images/ch4/overfitting.png\\">\\n        <figcaption>\\n          Wikimedia overfitting diagram: blue = training error, red = validation error over epochs.\\n          This matches the lecture\u2019s explanation of monitoring loss curves to detect overfitting.\\n        </figcaption>\\n      </figure>\\n\\n      <h3 id=\\"accuracy-computation-and-the-mean-of-booleans-trick\\">Accuracy computation (and the \u201cmean of booleans\u201d trick)</h3>\\n      <p>\\n        The model outputs probabilities. For predictions, round to 0/1:\\n      </p>\\n      <p>\\n        $$\\\\hat{y}=\\\\text{round}(p).$$\\n      </p>\\n      <p>\\n        Then accuracy is the mean of element-wise equality:\\n        in Python, <code>True</code> behaves like 1 and <code>False</code> like 0.\\n      </p>\\n\\n      <div class=\\"codeblock\\">\\n        <div class=\\"codebar\\">\\n          <div class=\\"left\\">\\n            <div class=\\"dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n            <span class=\\"lang\\">Python</span>\\n            <span class=\\"mini\\">Train/test accuracy</span>\\n          </div>\\n          \\n        </div>\\n        <div class=\\"editor\\">\\n          <div class=\\"gutter\\"></div>\\n          <pre data-ln=\\"\\"><code id=\\"code-acc\\" class=\\"language-python\\">with torch.no_grad():\\n    p_train = model(X_train_t).numpy()\\n    p_test  = model(X_test_t).numpy()\\n\\n# probabilities -&gt; class predictions\\nyhat_train = np.round(p_train)\\nyhat_test  = np.round(p_test)\\n\\ntrain_acc = (yhat_train.reshape(-1) == y_train).mean()\\ntest_acc  = (yhat_test.reshape(-1)  == y_test).mean()\\n\\nprint(\\"train accuracy:\\", train_acc)\\nprint(\\"test  accuracy:\\", test_acc)</code></pre>\\n        </div>\\n      </div>\\n\\n      <div class=\\"callout.blue\\">\\n        <div class=\\"title\\">Lecture exercise (kept, but made explicit)</div>\\n        <p>\\n          Modify the training loop to also compute accuracy each epoch (train and test),\\n          store them in arrays, and plot accuracy vs epoch. You should typically see loss go down while accuracy goes up.\\n        </p>\\n      </div>\\n    </section>\\n\\n    \x3c!-- ===================================================== --\x3e\\n    <section id=\\"stability\\">\\n      <h2 id=\\"8-a-better-logistic-regression-in-pytorch-bcewithlogitsloss\\">8) A Better Logistic Regression in PyTorch: <code>BCEWithLogitsLoss</code></h2>\\n\\n      <p>\\n        The lecture points out a practical numerical-stability issue:\\n        explicitly computing sigmoid uses exponentials, and BCE uses logs.\\n        PyTorch provides a stable combined loss that works directly on logits.\\n      </p>\\n\\n      <p>\\n        Conceptually, it\u2019s still the same loss, just computed in a numerically stable way.\\n        For a single logit $a$ and label $y\\\\in\\\\{0,1\\\\}$, one stable form is:\\n        $$\\\\ell(a,y)=\\\\max(a,0) - a\\\\,y + \\\\log\\\\left(1+e^{-|a|}\\\\right).$$\\n      </p>\\n\\n      <p>\\n        Instead of computing \\\\(p=\\\\sigma(a)\\\\) then BCE, we keep the model output as:\\n      </p>\\n      <p>\\n        $$a=w^\\\\top x+b\\\\quad\\\\text{(logit)},$$\\n      </p>\\n      <p>\\n        and use <code>nn.BCEWithLogitsLoss</code>.\\n      </p>\\n\\n      <div class=\\"codeblock\\">\\n        <div class=\\"codebar\\">\\n          <div class=\\"left\\">\\n            <div class=\\"dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n            <span class=\\"lang\\">Python</span>\\n            <span class=\\"mini\\">Stable version: logits + BCEWithLogitsLoss</span>\\n          </div>\\n          \\n        </div>\\n        <div class=\\"editor\\">\\n          <div class=\\"gutter\\"></div>\\n          <pre data-ln=\\"\\"><code id=\\"code-logits\\" class=\\"language-python\\"># Model now outputs logits (no Sigmoid layer!)\\nmodel = nn.Linear(D, 1)\\n\\n# Stable combined loss\\ncriterion = nn.BCEWithLogitsLoss()\\n\\noptimizer = torch.optim.Adam(model.parameters(), lr=1e-3)\\n\\n# Training loop is the same shape, but now model(X) returns logits\\nfor epoch in range(epochs):\\n    optimizer.zero_grad()\\n    logits_train = model(X_train_t)                 # any real number\\n    loss_train = criterion(logits_train, y_train_t)\\n    loss_train.backward()\\n    optimizer.step()\\n\\n# Predictions: logits &gt; 0  &lt;=&gt;  sigmoid(logits) &gt; 0.5\\nwith torch.no_grad():\\n    logits_test = model(X_test_t).numpy()\\nyhat_test = (logits_test &gt; 0).astype(np.int64).reshape(-1)</code></pre>\\n        </div>\\n      </div>\\n\\n      <div class=\\"callout.purple\\">\\n        <div class=\\"title\\">Prediction rule without sigmoid</div>\\n        <p>\\n          Because \\\\(\\\\sigma(a)\\\\ge 0.5 \\\\iff a\\\\ge 0\\\\), you can classify directly using the sign of the logit:\\n          \\\\(a&gt;0 \\\\Rightarrow \\\\hat{y}=1\\\\), else \\\\(\\\\hat{y}=0\\\\).\\n        </p>\\n      </div>\\n    </section>\\n\\n    \x3c!-- ===================================================== --\x3e\\n    <section id=\\"save\\">\\n      <h2 id=\\"9-saving-and-loading-models-and-downloading-from-colab\\">9) Saving and Loading Models (and Downloading from Colab)</h2>\\n\\n      <h3 id=\\"the-key-object-state-dict\\">The key object: <code>state_dict</code></h3>\\n      <p>\\n        In PyTorch, a model\u2019s parameters live in an ordered dictionary returned by:\\n      </p>\\n      <p>\\n        $$\\\\texttt{model.state\\\\_dict()} \\\\Rightarrow \\\\{\\\\text{weights},\\\\text{biases},\\\\dots\\\\}.$$\\n      </p>\\n\\n      <div class=\\"codeblock\\">\\n        <div class=\\"codebar\\">\\n          <div class=\\"left\\">\\n            <div class=\\"dots\\"><span class=\\"dot red\\"></span><span class=\\"dot yellow\\"></span><span class=\\"dot green\\"></span></div>\\n            <span class=\\"lang\\">Python</span>\\n            <span class=\\"mini\\">Save + reload (recommended pattern)</span>\\n          </div>\\n          \\n        </div>\\n        <div class=\\"editor\\">\\n          <div class=\\"gutter\\"></div>\\n          <pre data-ln=\\"\\"><code id=\\"code-save\\" class=\\"language-python\\"># Save\\ntorch.save(model.state_dict(), \\"mymodel.pt\\")\\n\\n# Recreate the same architecture (must match!)\\nmodel2 = nn.Sequential(\\n    nn.Linear(D, 1),\\n    nn.Sigmoid()\\n)\\n\\n# Load weights\\nstate = torch.load(\\"mymodel.pt\\", map_location=\\"cpu\\")\\nmodel2.load_state_dict(state)\\nmodel2.eval()\\n\\n# Verify identical accuracy (example)\\nwith torch.no_grad():\\n    p_test2 = model2(X_test_t).numpy()\\nyhat_test2 = np.round(p_test2).reshape(-1)\\nprint(\\"test accuracy (reloaded):\\", (yhat_test2 == y_test).mean())</code></pre>\\n        </div>\\n      </div>\\n\\n      <h3 id=\\"colab-download\\">Colab download</h3>\\n      <p>\\n        The lecture gave two ways:\\n      </p>\\n      <ol>\\n        <li>Use the Colab file browser sidebar and click \u201cDownload\u201d on <code>mymodel.pt</code>.</li>\\n        <li>Use code: <code>from google.colab import files; files.download(\\"mymodel.pt\\")</code>.</li>\\n      </ol>\\n    </section>\\n\\n    \x3c!-- ===================================================== --\x3e\\n    <section id=\\"neuron\\">\\n      <h2 id=\\"10-why-logistic-regression-is-a-neuron\\">10) Why Logistic Regression is a \u201cNeuron\u201d</h2>\\n\\n      <p>\\n        A single neuron-like computation in deep learning is:\\n      </p>\\n      <p>\\n        $$a=\\\\sum_{i=1}^{D} w_i x_i + b,\\\\qquad \\\\hat{y}=\\\\sigma(a)\\\\ \\\\text{(then threshold)}.$$\\n      </p>\\n\\n      <p>\\n        So logistic regression has the same mathematical shape as a simple artificial neuron: a weighted sum + bias,\\n        followed by a nonlinear activation. Deep networks stack many such units, but the biology analogy should not be\\n        pushed too far; artificial neurons are engineering abstractions, not faithful biological neuron simulations.\\n      </p>\\n\\n      <p>\\n        The lecture\u2019s biological analogy:\\n      </p>\\n      <ul>\\n        <li>Inputs \\\\(x_i\\\\) correspond to signals from many incoming connections (dendrites).</li>\\n        <li>Weights \\\\(w_i\\\\) represent connection strengths (strong vs weak).</li>\\n        <li>The sign of \\\\(w_i\\\\) represents excitatory (positive) vs inhibitory (negative) influence.</li>\\n        <li>A threshold-like effect resembles the \u201call-or-nothing\u201d firing behavior.</li>\\n      </ul>\\n\\n      <div class=\\"callout.green\\">\\n        <div class=\\"title\\">Interpretation of weights (kept from lecture)</div>\\n        <p>\\n          If \\\\(w_i\\\\approx 0\\\\), feature \\\\(x_i\\\\) has little effect on the output. If \\\\(|w_i|\\\\) is large,\\n          small changes in \\\\(x_i\\\\) strongly affect the output. The sign determines direction of influence.\\n        </p>\\n      </div>\\n    </section>\\n\\n    \x3c!-- ===================================================== --\x3e\\n    <section id=\\"splits\\">\\n      <h2 id=\\"11-train-validation-test-why-splits-exist-and-how-kaggle-changes-the-words\\">11) Train / Validation / Test: Why Splits Exist (and How Kaggle Changes the Words)</h2>\\n\\n      <h3 id=\\"why-split-at-all\\">Why split at all?</h3>\\n      <p>\\n        The whole point of a classifier is to work on <em>future</em> unseen data.\\n        If you only measure performance on past seen data, you can fool yourself.\\n      </p>\\n\\n      <div class=\\"callout.red\\">\\n        <div class=\\"title\\">Overfitting intuition (from lecture)</div>\\n        <p>\\n          Complex models can fit training data extremely well but generalize poorly.\\n          We want a model that balances being expressive enough to learn patterns,\\n          but not so expressive that it memorizes noise.\\n        </p>\\n      </div>\\n\\n      <figure>\\n        <img alt=\\"Bias and variance contributing to total error (bias-variance tradeoff intuition)\\" src=\\"/tutorials/images/ch4/bias-variance-total-error-local.svg\\">\\n        <figcaption>\\n          Local bias-variance diagram: total error is a combination of bias and variance (and irreducible noise).\\n          This supports the lecture\u2019s \u201cnot too simple, not too complex\u201d message.\\n        </figcaption>\\n      </figure>\\n\\n      <h3 id=\\"train-vs-validation-vs-test-the-naming-confusion\\">Train vs validation vs test: the naming confusion</h3>\\n      <p>\\n        If you only split into two sets, the \u201ctest\u201d set is effectively acting as a validation set\\n        (you are using it to validate generalization). That\u2019s why people sometimes say\\n        \u201ctrain/validation\u201d and sometimes \u201ctrain/test\u201d for the same two-way split.\\n      </p>\\n\\n      <h3 id=\\"kaggle-contest-semantics-from-the-lecture\\">Kaggle contest semantics (from the lecture)</h3>\\n      <ul>\\n        <li>Kaggle provides a labeled \u201ctrain\u201d set and an unlabeled \u201ctest\u201d set.</li>\\n        <li>You can\u2019t compute test accuracy yourself (labels are hidden).</li>\\n        <li>So you split Kaggle\u2019s train into <strong>train + validation</strong> to tune choices.</li>\\n        <li>Public leaderboard vs private leaderboard: private is used for final ranking to reduce overfitting to the public test feedback.</li>\\n      </ul>\\n\\n      <h3 id=\\"cross-validation-kept-with-clean-wording\\">Cross-validation (kept, with clean wording)</h3>\\n      <p>\\n        A common classical ML approach is \\\\(k\\\\)-fold cross-validation:\\n        split data into \\\\(k\\\\) parts, train on \\\\(k-1\\\\), validate on the remaining part,\\n        repeat \\\\(k\\\\) times, then summarize validation performance.\\n        The lecture notes it\u2019s less common in deep learning due to large datasets and long training times.\\n      </p>\\n\\n      <h3 id=\\"what-is-validation-used-for\\">What is validation used for?</h3>\\n      <p>\\n        Validation performance is how you choose <strong>hyperparameters</strong>:\\n        learning rate, optimizer type, feature subsets, model architecture, number of layers/units,\\n        activation choices, etc. You can\u2019t just \u201cgradient descent\u201d on architecture, so you use\\n        trial-and-error guided by validation scores.\\n      </p>\\n\\n      <figure>\\n        <img alt=\\"Learning curve (training vs validation score vs amount of training data)\\" src=\\"/tutorials/images/ch4/learning-curves-naive-bayes.svg\\">\\n        <figcaption>\\n          Local learning-curve diagram: training vs validation score as training data grows.\\n          This supports the lecture\u2019s point that validation helps diagnose bias/variance issues and whether more data would help.\\n        </figcaption>\\n      </figure>\\n    </section>\\n\\n    \x3c!-- ===================================================== --\x3e\\n    <section id=\\"summary\\">\\n      <h2 id=\\"12-summary-exercises\\">12) Summary + Exercises</h2>\\n\\n      <div class=\\"callout.blue\\">\\n        <div class=\\"title\\">What you should now understand (directly from lecture topics)</div>\\n        <ul>\\n          <li>What a linear classifier is: boundary \\\\(w^\\\\top x+b=0\\\\), logit \\\\(a=w^\\\\top x+b\\\\).</li>\\n          <li>How predictions work: sign test or sigmoid + threshold.</li>\\n          <li>Why logistic regression is linear + sigmoid, and why \u201clogit\u201d matters.</li>\\n          <li>Why classification uses cross-entropy (binary cross entropy for two classes).</li>\\n          <li>The PyTorch training loop pattern: zero_grad \u2192 forward \u2192 loss \u2192 backward \u2192 step.</li>\\n          <li>Why scaling (StandardScaler) and train/test split matter.</li>\\n          <li>How to compute accuracy correctly (including the boolean-mean trick).</li>\\n          <li>How to save/load models using <code>state_dict</code>.</li>\\n          <li>Why BCEWithLogitsLoss is numerically safer than sigmoid + BCELoss.</li>\\n          <li>Train/validation/test semantics, Kaggle workflow, and what validation is for (hyperparameter tuning).</li>\\n        </ul>\\n      </div>\\n\\n      <div class=\\"callout.green\\">\\n        <div class=\\"title\\">Exercises (from the lecture, made precise)</div>\\n        <ol>\\n          <li>\\n            During training, compute <strong>train accuracy</strong> and <strong>test accuracy</strong> each epoch.\\n            Store them in arrays and plot them later (or print every N epochs). Verify: loss \u2193 tends to imply accuracy \u2191.\\n          </li>\\n          <li>\\n            Switch from <code>nn.Sequential(Linear,Sigmoid)</code> + <code>BCELoss</code> to <code>Linear</code> + <code>BCEWithLogitsLoss</code>.\\n            Confirm you get similar accuracy, and change prediction rule to <code>(logits &gt; 0)</code>.\\n          </li>\\n          <li>\\n            Experiment with learning rates \\\\(10^{-2}, 10^{-3}, 10^{-4}\\\\) and compare convergence behavior and final test accuracy.\\n          </li>\\n        </ol>\\n      </div>\\n\\n      <p class=\\"mini\\">\\n        Image sources:\\n        <a href=\\"https://commons.wikimedia.org/wiki/Special:FilePath/Svm%20separating%20hyperplanes%20%28SVG%29.svg\\">SVM hyperplanes</a>,\\n        <a href=\\"https://commons.wikimedia.org/wiki/Special:FilePath/Sigmoid-function.svg\\">Sigmoid</a>,\\n        <a href=\\"https://commons.wikimedia.org/wiki/Special:FilePath/Gradient%20descent.gif\\">Gradient descent</a>,\\n        <a href=\\"https://commons.wikimedia.org/wiki/Special:FilePath/Overfitting.png\\">Overfitting</a>,\\n        <a href=\\"https://commons.wikimedia.org/wiki/Special:FilePath/Bias%20and%20variance%20contributing%20to%20total%20error.svg\\">Bias-variance</a>,\\n        <a href=\\"https://commons.wikimedia.org/wiki/Special:FilePath/Learning%20Curves%20%28Naive%20Bayes%29.png\\">Learning curves</a>.\\n      </p>\\n    </section>\\n  </div>"}'),l={title:"Linear Classification in PyTorch",slug:"/part4-ml-foundations/04-linear-classification",description:"A student-friendly chapter that explains linear decision boundaries, logistic regression, and a complete PyTorch training loop end-to-end. Diagrams are saved locally under assets/images/ch4 (downloaded from Wikimedia...",sidebar_label:"4. Linear classification",pagination_label:"4. Linear classification",hide_title:!0,hide_table_of_contents:!0},c=void 0,d={},p=[];function g(n){return(0,t.jsx)(o.A,{content:r})}function h(n={}){const{wrapper:e}={...(0,s.R)(),...n.components};return e?(0,t.jsx)(e,{...n,children:(0,t.jsx)(g,{...n})}):g()}}}]);